create table if not exists public.strava_connections (id uuid primary key default gen_random_uuid(), user_id uuid not null unique references auth.users(id) on delete cascade, athlete_id text, access_token text not null, refresh_token text not null, expires_at timestamptz, scope text, updated_at timestamptz not null default now(), created_at timestamptz not null default now()); create table if not exists public.strava_oauth_states (state text primary key, user_id uuid not null references auth.users(id) on delete cascade, created_at timestamptz not null default now()); alter table public.strava_connections enable row level security; alter table public.strava_oauth_states enable row level security; create policy "Users can read their own Strava connection" on public.strava_connections for select to authenticated using (auth.uid() = user_id); create policy "Users can delete their own Strava connection" on public.strava_connections for delete to authenticated using (auth.uid() = user_id); create index if not exists strava_oauth_states_created_at_idx on public.strava_oauth_states(created_at);
